CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY, usuario TEXT UNIQUE NOT NULL, senha_hash TEXT NOT NULL, papel TEXT NOT NULL CHECK(papel IN ('admin','clinica')));
CREATE TABLE IF NOT EXISTS sessoes (token_hash TEXT PRIMARY KEY, usuario_id INTEGER NOT NULL REFERENCES usuarios(id), expira INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS enderecos (id INTEGER PRIMARY KEY AUTOINCREMENT, cep TEXT NOT NULL, logradouro TEXT NOT NULL, numero TEXT NOT NULL, complemento TEXT, bairro TEXT NOT NULL, cidade TEXT NOT NULL, uf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tutores (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, telefone TEXT NOT NULL, endereco_id INTEGER NOT NULL REFERENCES enderecos(id));
CREATE TABLE IF NOT EXISTS especies (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS racas (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, especie_id INTEGER NOT NULL REFERENCES especies(id), UNIQUE(nome,especie_id), UNIQUE(id,especie_id));
CREATE TABLE IF NOT EXISTS veterinarios (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, crmv TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS animais (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, nascimento TEXT, tutor_id INTEGER NOT NULL REFERENCES tutores(id), especie_id INTEGER NOT NULL REFERENCES especies(id), raca_id INTEGER, microchip TEXT UNIQUE NOT NULL, versao INTEGER NOT NULL DEFAULT 1, ativo INTEGER NOT NULL DEFAULT 1 CHECK(ativo IN (0,1)), FOREIGN KEY(raca_id,especie_id) REFERENCES racas(id,especie_id));
CREATE TABLE IF NOT EXISTS consultas (id INTEGER PRIMARY KEY AUTOINCREMENT, animal_id INTEGER NOT NULL REFERENCES animais(id), veterinario_id INTEGER NOT NULL REFERENCES veterinarios(id), data TEXT NOT NULL, descricao TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vacinas (id INTEGER PRIMARY KEY AUTOINCREMENT, animal_id INTEGER NOT NULL REFERENCES animais(id), veterinario_id INTEGER NOT NULL REFERENCES veterinarios(id), data TEXT NOT NULL, nome TEXT NOT NULL, lote TEXT NOT NULL, antirrabica INTEGER NOT NULL CHECK(antirrabica IN (0,1)));
CREATE TABLE IF NOT EXISTS operacoes (id INTEGER PRIMARY KEY AUTOINCREMENT, animal_id INTEGER NOT NULL REFERENCES animais(id), chave TEXT UNIQUE NOT NULL, tipo TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDENTE' CHECK(status IN ('PENDENTE','FALHA','ENVIADO')), tentativas INTEGER NOT NULL DEFAULT 0, protocolo TEXT, erro TEXT, criado TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, atualizado TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_operacoes_animal ON operacoes(animal_id,id);
CREATE INDEX IF NOT EXISTS idx_consultas_animal ON consultas(animal_id,data);
CREATE INDEX IF NOT EXISTS idx_vacinas_animal ON vacinas(animal_id,data);
